// Bad Apple player for an ESP32 with a TFT display (TFT_eSPI).
//
// The video is stored in src/vid.h, generated by encoder/main.py.
// This file decodes it one frame at a time and draws it on the screen.
// Lines marked "CHANGED:" explain a change from an earlier version.
//
// Stream format (must match encoder/main.py):
//   - The stream is one long sequence of bits, read from bit 63 down to bit 0 of each v[] word.
//   - It is a list of runs. A run is a colour (black or white) and a length.
//   - The first run's colour is stored as one bit. After that the colour alternates,
//     unless the previous run had the maximum length (see below).
//   - A run length is stored as (length - 1) using a variable-length code (VLQ).
//     The value is split into segments of VLQ_BITS bits, least significant segment first.
//     Each segment after the first is preceded by a 1 bit (another segment follows)
//     or a 0 bit (the code ends here).
//   - A run whose stored value is MAX_RUN_RAW is followed by an explicit colour bit,
//     because the colour does not necessarily alternate after it.
//   - Frames are not separate in the stream. A run can continue into the next frame.

#include <SPI.h>
#include <TFT_eSPI.h>

#include "vid.h"  // frames_n, byte_n and the data array v[]

// ---------- Settings ----------

// CHANGED: settings moved to named constants at the top (was: magic numbers in the code).

// 1 = print debug information on the serial monitor (115200 baud). 0 = no serial output.
#define DEBUG_SERIAL 1

// 1 = draw a coloured test pattern for one second at startup. 0 = start with a black screen.
// CHANGED: the test pattern is now off by default. It only covered the picture and was
// drawn over by the first frame anyway.
#define SHOW_TEST_PATTERN 0

// Picture size in pixels. The encoder keeps columns 30..207 of the source video
// (178 px wide) and 134 rows.
const uint8_t VIDEO_W = 178;
const uint8_t VIDEO_H = 134;

// Pause between two stored frames in milliseconds. The encoder keeps every 3rd source frame.
// Tune this to make the video play at the right speed.
const uint16_t FRAME_DELAY_MS = 30;

// Pause after the last frame before the video starts again.
const uint16_t LOOP_PAUSE_MS = 5000;

const uint16_t COLOR_ZERO = TFT_BLACK;
const uint16_t COLOR_ONE = TFT_WHITE;

// VLQ_BITS (segment widths of a run length code) and MAX_RUN_RAW (the largest stored value)
// come from vid.h. The encoder writes them, so they always match the data.
// A run stored with MAX_RUN_RAW is followed by an explicit colour bit.
// CHANGED: the old code compared the value after adding 1 to this constant. The encoder
// compares the stored value, so the check never matched and the stream could fall out of step.

// ---------- Decoder state ----------

// Position in the stream: index into v[] and bit index inside that word (0 = bit 63).
uint32_t word_index = 0;
uint8_t bit_index = 0;

// The run that is being drawn.
uint32_t run_left = 0;          // pixels still to draw in the current run
bool run_color = 0;             // colour of the current run (1 = white)
bool color_is_explicit = true;  // true: the next run's colour is stored in the stream

// Set when the decoder needs a bit after the last word of v[].
// CHANGED: the old code read past the end of v[] (undefined behaviour, garbage on screen).
// Now the decoder stops and the last picture stays on screen until the video restarts.
bool stream_ended = false;

uint16_t frame_cnt = 0;

TFT_eSPI tft = TFT_eSPI();

// ---------- Bit reader ----------

// CHANGED: the bit reading was copied four times in the old code. It now lives in these
// three helpers, so the position update is written once.

// Returns the next bit without moving forward.
uint8_t peekBit() {
  if (word_index >= byte_n) {
    stream_ended = true;
    return 0;
  }
  return (v[word_index] >> (63 - bit_index)) & 1;
}

// Returns the next bit and moves forward by one.
uint8_t readBit() {
  uint8_t bit = peekBit();

  bit_index++;
  if (bit_index == 64) {
    bit_index = 0;
    word_index++;
  }

  return bit;
}

// Reads count bits and returns them as a number, most significant bit first.
uint32_t readBits(uint8_t count) {
  uint32_t value = 0;

  for (uint8_t i = 0; i < count; i++) {
    value = (value << 1) | readBit();
  }

  return value;
}

// Reads one run length code and returns the stored value (length - 1).
uint32_t readRunRaw() {
  uint32_t value = 0;
  uint8_t shift = 0;

  for (uint8_t seg = 0; seg < sizeof(VLQ_BITS) / sizeof(VLQ_BITS[0]); seg++) {
    if (seg == 0) {
      // The first segment has a prefix bit too. The encoder always writes 0 here, so it is skipped.
      readBit();
    } else {
      // 0 = the code ends here. The 0 is not consumed: it is the start of the next code.
      if (peekBit() == 0) {
        break;
      }
      readBit();
    }

    value |= readBits(VLQ_BITS[seg]) << shift;
    shift += VLQ_BITS[seg];
  }

  return value;
}

// Starts the next run: reads its colour (if the stream stores it) and its length.
void startNextRun() {
  if (color_is_explicit) {
    run_color = readBit();
    color_is_explicit = false;
  } else {
    run_color = !run_color;
  }

  uint32_t raw = readRunRaw();
  run_left = raw + 1;

  if (raw == MAX_RUN_RAW) {
    color_is_explicit = true;
  }
}

// ---------- Drawing ----------

// Draws one frame. Runs can cross the end of a frame; the rest of the run is drawn in the next frame.
void drawFrame() {
  if (stream_ended) {
    return;
  }

  uint8_t x = 0;
  uint8_t y = 0;

  while (y < VIDEO_H) {
    if (run_left == 0) {
      startNextRun();
      if (stream_ended) {
        return;
      }
    }

    // Draw as much of the run as fits on the current row.
    uint8_t room_on_row = VIDEO_W - x;
    uint8_t pixels = (run_left < room_on_row) ? run_left : room_on_row;

    tft.drawFastHLine(x, y, pixels, run_color ? COLOR_ONE : COLOR_ZERO);

    x += pixels;
    run_left -= pixels;

    if (x == VIDEO_W) {
      x = 0;
      y++;
    }
  }
}

// ---------- Arduino entry points ----------

void setup() {
  Serial.begin(115200);
  tft.begin();
  tft.fillScreen(TFT_BLACK);
  tft.setRotation(3);

#if DEBUG_SERIAL
  Serial.println("Initialised");  // CHANGED: typo fixed ("Succesfully")
#endif

#if SHOW_TEST_PATTERN
  tft.drawFastHLine(0, 0, 238, TFT_BLUE);
  tft.drawFastHLine(0, 10, 178, TFT_GOLD);
  tft.drawFastHLine(178, 10, 60, TFT_ORANGE);
  tft.drawFastHLine(119, 67, 119, TFT_YELLOW);
  tft.drawFastHLine(119, 0, 119, TFT_PURPLE);
  tft.drawFastVLine(0, 0, 134, TFT_RED);
  delay(1000);
#endif
}

void loop() {
  drawFrame();

  frame_cnt++;

  if (frame_cnt == frames_n) {
    // Reset the decoder to the start of the stream and play the video again.
    frame_cnt = 0;
    word_index = 0;
    bit_index = 0;
    run_left = 0;
    color_is_explicit = true;
    stream_ended = false;

#if DEBUG_SERIAL
    Serial.println("Display_finished");
#endif

    tft.fillScreen(TFT_BLACK);
    delay(LOOP_PAUSE_MS);
  }

  delay(FRAME_DELAY_MS);
}
